    "explanation": "Từ nội dung bài nói, người nói đề cập trực tiếp đến thông tin liên quan đến phương án (C) 'Roofmaintenance' (Bảo trì mái nhà).",
    "transcript": "Welcome to your house works on today's episode we'll go over how you can maintain and make minor repairs to the roof of your home the first thing to do is to invest in a few special tools like a trowel and crowbar it's important to choose some that are trowel and crowbar it's important to choose some that are high quality because you'll use them for many years with your trowel and some roof cement you can seal any cracks or chips the Crowbar will help you remove loose shingles that you can then replace now I highly recommend you take photos of your roof every year so that you can track its overall condition",
