    "passage": "Thanks everyone for attending today's free public lecture sponsored by the Springfield pharmacists Association so we've received lots of requests for information on growing a vegetable garden people want to know how to keep their Garden healthy and get the vegetables they want the first thing we recommend is regular the vegetables they want the first thing we recommend is regular soil testing since this is September all soil samples in the next 6 weeks should be taken from the same depth as seen on this chart Oh and before you leave today please sign up for our mailing list to stay informed of future lectures",
