    "questionText": "What is indicated about the Bryant Foyer?",
    "audioUrl": null,
    "imageUrl": null,
    "passage": "TEST The Bryant Foyer is one of the premier event spaces in our area. Set on a hill, it has and the river. Built in 1897, it was the home of the Francona Charitable Trust until expansive windows that provide sweeping views of the adjacent botanical gardens its renovation just over a year ago. Today, the space can accommodate up to 200 guests and is ideal for wedding receptions, office parties, and panel presentations. With its marble floors, cathedral ceiling, and stunning artwork, the Bryant Foyer is the ideal location for your next gathering. The on-site restaurant, Andito's, caters our events and also, operates as its own business. This farm-to-table restaurant, headed by chef Michaela Rymond, meets all dietary needs and has revolutionized the local food scene. Area residents know to plan far in advance to get a seat. To reserve the event space or to make a dinner reservation, give us a call at 216-555-0157.",
    "bilingualPassage": "KIỂM TRA Bryant Foyer là một trong những không gian tổ chức sự kiện hàng đầu trong khu vực của chúng tôi. Nằm trên một ngọn đồi, nó có và dòng sông. Được xây dựng vào năm 1897, đây là trụ sở của Quỹ từ thiện Francona cho đến khi có cửa sổ mở rộng cho tầm nhìn bao quát ra các vườn bách thảo lân cận nó mới được cải tạo cách đây hơn một năm. Ngày nay, không gian có thể chứa tới 200 khách và là nơi lý tưởng để tổ chức tiệc cưới, tiệc văn phòng và thuyết trình. Với sàn lát đá cẩm thạch, trần nhà thờ và tác phẩm nghệ thuật tuyệt đẹp, Bryant Foyer là địa điểm lý tưởng cho buổi tụ tập tiếp theo của bạn. Nhà hàng trong khuôn viên, Andito's, phục vụ các sự kiện của chúng tôi và cũng hoạt động như của riêng mình. kinh doanh. Nhà hàng từ nông trại đến bàn ăn này do đầu bếp Michaela Rymond đứng đầu, đáp ứng tất cả nhu cầu ăn kiêng và đã cách mạng hóa nền ẩm thực địa phương. Người dân khu vực biết lên kế hoạch từ trước để có được chỗ ngồi. Để đặt chỗ tổ chức sự kiện hoặc đặt bữa tối, hãy gọi cho chúng tôi theo số 216-555-0157.",
    "options": {
      "A": "It is located on the shores of a lake.",
      "B": "It has recently been renovated.",
      "C": "It will build a botanical garden for guests.",
      "D": "It is reserved solely for corporate events."
    },
    "correctAnswer": "B",
    "explanation": "Đáp án chính xác là (B): 'It has recently been renovated.' (Nó gần đây đã được cải tạo.).\nThông tin trong văn bản tương ứng với nội dung của phương án (B). Các phương án còn lại gây nhiễu do thông tin không được nhắc đến hoặc trái ngược với bài đọc.",
    "transcript": "(A) It is located on the shores of a lake. (B) It has recently been renovated. (C) It will build a botanical garden for guests. (D) It is reserved solely for corporate events.",
    "translation": "Điều gì được chỉ ra về Sảnh Bryant?",
    "groupTitle": "Questions 147–148 refer to the following notice."
