    "questionText": "Forwhom is thenoticemostlikely intended?",
    "audioUrl": null,
    "imageUrl": null,
    "passage": "TEST This season's excellent weather has yielded a substantial harvest of fruits and wishing to donate surplus produce to community organizations can do so by visiting vegetables, in many cases more than growers may find buyers for. Those of you Vosey Farm and Garden's Web site (www.vfgrdn.org), where you will find our list of drop-off locations. If you need us to come to you instead, please contact us. We will reach out to one of the many independent truck drivers who have kindly volunteered to transport and guickly distribute your food donations to vetted groups that need it. Check our Web site for more information about this service as well as for insights into topics related to farming and gardening in the Northern Great Plains region.",
    "bilingualPassage": "KIỂM TRA Thời tiết tuyệt vời của mùa này đã mang lại một vụ thu hoạch đáng kể các loại trái cây và mong muốn quyên góp sản phẩm dư thừa cho các tổ chức cộng đồng có thể làm như vậy bằng cách đến thăm rau, trong nhiều trường hợp, nhiều hơn mức người trồng có thể tìm được người mua. Những người trong số bạn Trang web của Nông trại và Vườn Vosey (www.vfgrdn.org), nơi bạn sẽ tìm thấy danh sách của chúng tôi về các địa điểm trả khách. Nếu bạn cần chúng tôi đến thay bạn, vui lòng liên hệ với chúng tôi. Chúng tôi sẽ liên hệ với một trong những nhiều tài xế xe tải độc lập đã tình nguyện vận chuyển và nhanh chóng phân phối số tiền quyên góp thực phẩm của bạn cho các nhóm đã được kiểm duyệt cần nó. Kiểm tra của chúng tôi Trang web để biết thêm thông tin về dịch vụ này cũng như để hiểu rõ hơn về các chủ đề liên quan đến trồng trọt và làm vườn ở vùng đồng bằng lớn phía Bắc.",
