    "questionText": "Where most likely is the notice posted?",
    "audioUrl": null,
    "imageUrl": null,
    "passage": "We are delighted that you are joining us for today's event. [1] -. We ask that you adhere to the folowing guidelines to ensure that all attendees have an enjoyable experience. Upon entering the venue, please put any and all electronic devices in silent mode. Ringtones and lit screens are very distracting to both the performers and your fellow audience members.[2] . Moreover, audience members are not allowed to makeanaudioorvisualrecordingoftheperformance. Bags and other items in the aisles pose a safety concern. - [3] -. If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2. [4].Oneof ourattendantswill gladlyassistyouwiththat. Thank you for your cooperation.",
    "bilingualPassage": "Chúng tôi rất vui mừng khi bạn tham gia cùng chúng tôi trong sự kiện ngày hôm nay. [1] -. Chúng tôi yêu cầu điều đó bạn tuân thủ các nguyên tắc sau để đảm bảo rằng tất cả những người tham dự đều có trải nghiệm thú vị. Khi vào địa điểm, vui lòng đặt bất kỳ và tất cả các thiết bị điện tử ở chế độ im lặng. Nhạc chuông và màn hình sáng sẽ gây mất tập trung cho cả người biểu diễn và bạn. các khán giả đồng nghiệp.[2] . Hơn nữa, khán giả không được phép tạo bản ghi âm hoặc hình ảnh của buổi biểu diễn. Túi xách và các vật dụng khác ở lối đi gây lo ngại về an toàn. - [3] -. Nếu túi của bạn quá lớn để có thể đặt vừa dưới ghế, hãy cân nhắc cất nó vào tủ khóa chỉ với 2 đô la. [4]. Một trong những người phục vụ của chúng tôi sẽ sẵn lòng hỗ trợ bạn việc đó. Cảm ơn sự hợp tác của bạn.",
    "options": {
      "A": "In an airplane",
      "B": "In a concert hall",
      "C": "At a restaurant",
      "D": "At a post office"
    },
    "correctAnswer": "B",
    "explanation": "Đáp án chính xác là (B): 'In a concert hall' (Trong một phòng hòa nhạc).\nThông tin trong văn bản tương ứng với nội dung của phương án (B). Các phương án còn lại gây nhiễu do thông tin không được nhắc đến hoặc trái ngược với bài đọc.",
    "transcript": "(A) In an airplane (B) In a concert hall (C) At a restaurant (D) At a post office",
    "translation": "Thông báo có nhiều khả năng được đăng ở đâu nhất?",
    "groupTitle": "Questions 147–148 refer to the following notice."
