    "bilingualPassage": "laura.savard@orbitmail.scot\nTừ: cboyle@ceoleire.co.uk\nNgày: 25 tháng 5\nChủ đề: RE: Một số gợi ý Kính gửi bà Savard, Cảm ơn bạn đã đề nghị nhận đơn đặt hàng trực tuyến từ cửa hàng của tôi hoặc thanh toán các mặt hàng của bạn cho bạn ở Stranraer. Tình cờ là chị gái tôi và các con của chị ấy phải sống thêm để đi lại bằng đường hàng không hoặc tàu hỏa. Không cần sắp xếp gì cả, vì tôi rất vui được giao hàng gần đó ở Kirkcolm. Trước khi gặp họ, tôi sẽ lái chiếc xe thuê của mình tới nhà bạn và đưa tay cho bạn. giao hàng cho bạn. Như bạn đã biết, hàng hóa của tôi được làm thủ công 100%. Nếu có bất kỳ thiệt hại nào xảy ra trong quá trình vận chuyển,\n\nnhiều thiệt hại do người xử lý hành lý thiếu chú ý gây ra. Chính sách của tôi là giao những món đồ mà việc sửa chữa trở thành một thử thách tốn kém và tốn thời gian. Trong nhiều năm, tôi cũng đã thấy như vậy cá nhân bất cứ khi nào khả thi hoặc thuê dịch vụ chuyển phát nhanh trên mặt đất hoặc trên biển mà tôi tin tưởng. Tôi mong được gặp bạn vào ngày 5 tháng 6. Tôi dự kiến sẽ đến nhà bạn không muộn hơn 5 giờ chiều Trân trọng, Conor Boyle Ceoleire cổ điển BắcIrelandPhàDịch vụ Ngày phát hành: 26 tháng 5 Tên hành khách:ConorBoyle Khởi hànhBelfast:Thứ sáu,5 tháng sáu,1:05 chiều DockingatCairnryan:Thứ sáu,5 tháng sáu,3:20 chiều Hành lý: 1 vali (nhỏ), 2 hộp đựng dụng cụ (1 đàn mandolin, 1 đàn guitar) Phương tiện vận chuyển: Không Lớp tiêu chuẩn dành cho người lớn:55,00 Vui lòng đến 30 phút trước khi khởi hành. 40",
