    "id": 186,
    "part": "Part 7",
    "questionText": "What is indicated about TTA?",
    "audioUrl": null,
    "imageUrl": null,
    "passage": "Train to Achieve (TTA)--Our classes prepare you to succeed! Profiled in the latest Business Directions Nigeria newsletter, Train to Achieve (TTA) is one of the most innovative training providers in West Africa. By offering our classes entirely in online format, we bring the classroom to your home. All classes include individualized instruction and are taught by recognized professionals in their respective fields. Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any resume. For a complete list of class fees and schedules, visit our Web site at www.traintoachieve.org.ng. The following are some of our most popular classes. Introduction\n\nto Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online. Become a Successful Freelance Writer (TTA3283):Business writer Brenda Akande gives you expert guidance on how to hone your writing skills and sell your writing services. Starting an Internet Radio Station (TTA7629):Online radio host Natalie Kabiru shows you how to appeal to your target market and gives practical tips for setting up your broadcast service. Basics of Graphic Design (TTA7633): Veteran graphic designer Doug Umaru helps you acquire the basic skills needed to start a graphic design business. Discussion forum for students enrolled in Train to Achieve Class TTA1504\nPosted on: 21 May, 9:41 A.M. Posted by: Joseph Egbe\n\nSubject: Presentations\nViewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class. I look forward to sharing our learning experiences again for this class. Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business. I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods. It was helpful advice. 42 Egbe's Bakery--Unique baked-in flavours in every bite! TEST : Section 1:Explore our menu and price list .Section 2: Browse photos of our delicious treats : Section 3: Learn about our catering services ·Section4:Viewlistsof ingredients",
    "bilingualPassage": "Rèn luyện để đạt được (TTA)--Các lớp học của chúng tôi chuẩn bị cho bạn thành công! Được giới thiệu trong bản tin Định hướng kinh doanh mới nhất của Nigeria, Đào tạo để đạt được (TTA) là một trong những nhà cung cấp đào tạo sáng tạo nhất ở Tây Phi. Bằng cách cung cấp các lớp học của chúng tôi hoàn toàn ở dạng trực tuyến, chúng tôi mang lớp học đến tận nhà bạn. Tất cả các lớp học bao gồm hướng dẫn cá nhân và được giảng dạy bởi các chuyên gia được công nhận trong lĩnh vực tương ứng của họ lĩnh vực. Sau khi hoàn thành khóa học, bạn sẽ nhận được Chứng chỉ chính thức về Đào tạo, một bổ sung có giá trị cho bất kỳ sơ yếu lý lịch nào. Để có danh sách đầy đủ về học phí và lịch trình, hãy truy cập trang web của chúng tôi tại\n\nwww.traintoachieve.org.ng. Sau đây là một số lớp học phổ biến nhất của chúng tôi. Giới thiệu về Tiếp thị truyền thông xã hội (TTA1504): Được giảng dạy bởi tiếp thị cố vấn Marcus Akpan, lớp học trang bị cho bạn bí quyết để quảng bá doanh nghiệp của bạn trực tuyến. Trở thành Nhà văn tự do thành công (TTA3283): Nhà văn kinh doanh Brenda Akande cung cấp cho bạn hướng dẫn chuyên môn về cách trau dồi kỹ năng viết và bán hàng dịch vụ viết bài của bạn. Khởi động Đài phát thanh Internet (TTA7629): Người dẫn chương trình phát thanh trực tuyến Natalie Kabiru chỉ cho bạn cách thu hút thị trường mục tiêu và đưa ra những lời khuyên thiết thực để thiết lập dịch vụ phát sóng của bạn. Khái niệm cơ bản về Thiết kế Đồ họa (TTA7633): Nhà thiết kế đồ họa kỳ cựu Doug Umaru giúp bạn có được những kỹ năng cơ bản cần thiết để bắt đầu kinh doanh thiết kế đồ họa. Diễn đàn thảo luận dành cho học viên đăng ký khóa học Train\n\nto Reach Class TTA1504 Đăng vào: 21 tháng 5, 9:41 sáng Đăng bởi: Joseph Egbe Chủ đề: Thuyết trình Xem danh sách học sinh đăng ký vào lớp này, tôi nhớ đã trò chuyện với một số người. của các bạn trên diễn đàn lớp thiết kế poster tháng 1. Tôi mong muốn được chia sẻ của chúng tôi học lại kinh nghiệm cho lớp học này. Hôm qua tôi là sinh viên thứ hai gặp với Mr.Akpan trong một cuộc hội thảo truyền hình cá nhân về công việc kinh doanh của tôi. Tôi sở hữu một món ăn chiếc xe tải nơi tôi bán đồ nướng và khi tôi chia sẻ với ông Akpan về đề cương trang web của tôi, anh ấy đề nghị tôi thêm một phần có hình ảnh sống động về tất cả các món nướng của tôi. Đó là lời khuyên hữu ích. 42 Egbe's Bakery--Hương vị nướng độc đáo trong từng miếng bánh! KIỂM TRA : Phần 1:Khám phá thực đơn và bảng giá của chúng tôi .Phần 2: Duyệt ảnh các món ngon của chúng tôi : Phần 3: Tìm hiểu về dịch vụ ăn uống của chúng tôi ·Phần 4:Danh sách thành phần",
