    "id": 196,
    "part": "Part 7",
    "questionText": "What does the invoice suggest about Green Canyon?",
    "audioUrl": null,
    "imageUrl": null,
    "passage": "OrbysDistributors Client: GreenCanyon Date: June10 Account:4352-0 Item Price Garden soil,33cubicmeters $1,170.00 Crushedgravel,30metrictons 1,710.00 Decorative stone,20metrictons 1,140.00 70pavingstones,.6x.6meters 630.00 Subtotal 4,650.00 Discount (10%) 465.00 Delivery charge 350.00 Grand Total 4,535.00 Please see the enclosed notice outlining important changes to your billing. Orbys Distributors To our valued customers:\nOur current invoicing system has been in use since Orbys Distributors was founded over twenty years ago. As a much-needed upgrade, we are switching to electronic invoicing. Starting August l, invoiceswillbegeneratedau\n\ntomaticallyeachmonthandwillbesent to the e-mail address associated with your company's account. Rest assured that our long-standing incentives remain in place:\n·A10%discountforordersofmorethan$4,000 A20%discountforcharitableorganizations Free deliveries to locations within 5 miles of one of our supply centers ·Free samples for members of our Frequent Buyer Club Moreinformation aboutourtransition toelectronic invoicingis available on our Web site. Thank you for your support. Orbys Distributors appreciates your business. 46\n*E-mail* TEST\nTo: MaryPeterson, Billing Department\nFrom: Tanvir Singh, Account Manager\nDate: September12\nSubject: Account1012-4 Hello Mary, I received a query\n\ntoday from William Tesoriero at Tesoriero Remodeling. His monthly invoice for August never arrived. As youknow, Mr. Tesoriero was one of our veryfirst customers. Sincewe first opened for business, he has made purchases from us on a regular basis. He is also a member of theFrequent Buyer Club. This is a customer we absolutely do not want to lose. I explained to him that the rollout of our electronic invoicing system did not go as smoothly as we had hoped and promised that this would not happen again. I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero. Tanvir",
    "bilingualPassage": "OrbysNhà phân phối Khách hàng:GreenCanyon Ngày:10 tháng 6 Tài khoản:4352-0 Giá mặt hàng Đất vườn,33mét khối $1.170,00 Sỏi nghiền,30 tấn 1.710,00 Đá trang trí,20metrictấn 1.140,00 70đá lát, 6x.6 mét 630,00 Tổng cộng 4.650,00 Giảm giá (10%) 465.00 Phí giao hàng 350,00 Tổng cộng 4.535,00 Vui lòng xem thông báo đính kèm nêu rõ những thay đổi quan trọng đối với việc thanh toán của bạn. Nhà phân phối Orbys Kính gửi quý khách hàng:\nHệ thống lập hóa đơn hiện tại của chúng tôi đã được sử dụng kể từ Orbys Nhà phân phối được thành lập hơn hai mươi năm trước. Là một điều rất cần thiết nâng cấp, chúng tôi đang chuyển sang hóa đơn điện tử. Bắt đầu từ tháng 8, hóa đơn sẽ được tạo tự động mỗi tháng và sẽ được gửi\n\ntới địa chỉ e-mail được liên kết với tài khoản của công ty bạn. Hãy yên tâm rằng các ưu đãi lâu dài của chúng tôi vẫn được giữ nguyên:\n·Giảm giá 10% cho đơn hàng trên 4.000 USD Giảm giá 20%cho các tổ chức từ thiện Giao hàng miễn phí đến các địa điểm trong phạm vi 5 dặm từ một trong những nguồn cung cấp của chúng tôi trung tâm ·Mẫu miễn phí dành cho thành viên Câu lạc bộ Người mua thường xuyên của chúng tôi Thông tin thêm về quá trình chuyển đổi sang hóa đơn điện tử của chúng tôi có sẵn trên trang web của chúng tôi. Cảm ơn bạn đã hỗ trợ.Orbys Các nhà phân phối đánh giá cao hoạt động kinh doanh của bạn. 46\n*E-mail* KIỂM TRA\nKính gửi: MaryPeterson, Phòng Thanh toán\nTừ: Tanvir Singh, Giám đốc tài khoản\nNgày: 12 tháng 9\nChủ đề: Tài khoản1012-4 Xin chào Mary,\n\nHôm nay tôi đã nhận được câu hỏi từ William Tesoriero tại Tesoriero Remodeling. hàng tháng của anh ấy hóa đơn cho tháng 8 không bao giờ đến. Như bạn đã biết, Mr.Tesoriero là một trong những khách hàng đầu tiên của chúng tôi. Kể từ khi chúng tôi mở cửa lần đầu tiên để kinh doanh, anh ấy thường xuyên mua hàng từ chúng tôi. Anh ấy cũng là thành viên của theCâu lạc bộ người mua thường xuyên. Đây là khách hàng mà chúng tôi hoàn toàn không muốn mất.Tôi giải thích với anh ấy rằng việc triển khai hệ thống hóa đơn điện tử của chúng tôi không diễn ra như ý muốn. suôn sẻ như chúng tôi đã hy vọng và hứa rằng điều này sẽ không xảy ra nữa. Tôi sẽ đánh giá cao nếu bạn có thể vui lòng điều tra vấn đề ngay lập tức và gửi hóa đơn tháng 8 cho ông Tesoriero. Tanvir",
    "options": {
      "A": "It does landscaping projects.",
      "B": "It designs highways.",
      "C": "It repairs old houses.",
      "D": "It operates a farm."
    },
    "correctAnswer": "A",
    "explanation": "Đáp án chính xác là (A): 'It does landscaping projects.' (Nó thực hiện các dự án cảnh quan.).\nThông tin trong văn bản tương ứng với nội dung của phương án (A). Các phương án còn lại gây nhiễu do thông tin không được nhắc đến hoặc trái ngược với bài đọc.",
    "transcript": "(A) It does landscaping projects. (B) It designs highways. (C) It repairs old houses. (D) It operates a farm.",
    "translation": "Hóa đơn gợi ý gì về Green Canyon?",
